def solve(matrix):
    # Determinant using Bareiss algorithm (fraction-free Gaussian elimination)
    # Empty matrix determinant is defined as 1.
    n = len(matrix)
    if n == 0:
        return 1
    # Ensure square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy to avoid mutating input
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1  # Denominator from previous step, initially 1
    for k in range(n-1):
        # Pivot handling: if zero, swap with a row below
        if a[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Compute new value using Bareiss formula
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n-1][n-1]

