{"task_id": "T13", "code": "def solve(coins, amount):
    # DP bottom-up: dp[i] = min coins for amount i
    # Initialize with amount+1 (larger than any possible count)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1
