{"task_id": "T25", "code": "def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses the fraction‑free Bareiss algorithm which runs in O(n³) and stays
    in integer arithmetic.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Copy matrix to avoid mutating input
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1  # denominator from previous step
    for k in range(n - 1):
        # If pivot is zero, try to swap with a lower row that has a non‑zero entry
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        if pivot == 0:
            return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update: exact division, no fractions
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]
