def solve(matrix):
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        assert len(row) == n
    # Make a copy
    A = [list(row) for row in matrix]
    det_sign = 1
    # Bareiss algorithm
    for k in range(n-1):
        # Pivot handling
        if A[k][k] == 0:
            # Find a row to swap
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Compute fraction-free update
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j])
