def solve(grid):
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= m:
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            stack.append((x - 1, y))
            stack.append((x + 1, y))
            stack.append((x, y - 1))
            stack.append((x, y + 1))
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

def solve(intervals):
    """Merge overlapping or touching intervals.
    Returns a new list without mutating the input.
    """
    if not intervals:
        return []
    # Make a shallow copy of intervals to avoid mutating caller's list
    intervals_copy = [list(iv) for iv in intervals]
    intervals_copy.sort(key=lambda x: x[0])
    merged = []
    for iv in intervals_copy:
        if not merged:
            merged.append(iv)
        else:
            last = merged[-1]
            if iv[0] <= last[1]:  # overlap or touch
                last[1] = max(last[1], iv[1])
            else:
                merged.append(iv)
    return merged

def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35, with a leading '-' for negative n.
    """
    if b < 2 or b > 36:
        raise ValueError('Base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n = abs(n)
    chars = []
    while n:
        n, rem = divmod(n, b)
        chars.append(digits[rem])
    return sign + ''.join(reversed(chars))

