    det_sign = 1
    # Bareiss algorithm
    for k in range(n - 1):
        # Pivot if zero
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Compute new element without fractions
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j])
                if k > 0:
                    A[i][j] //= A[k - 1][k - 1]
            A[i][k] = 0
