def solve(s):
    n = len(s)
    if n == 0:
        return ''
    best_start = 0
    best_len = 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1
    for i in range(n):
        # odd length palindrome centered at i
        l, r = expand(i, i)
        curr_len = r - l + 1
        if curr_len > best_len or (curr_len == best_len and l < best_start):
            best_start, best_len = l, curr_len
        # even length palindrome centered between i and i+1
        l, r = expand(i, i+1)
        curr_len = r - l + 1
        if curr_len > best_len or (curr_len == best_len and l < best_start):
            best_start, best_len = l, curr_len
    return s[best_start:best_start+best_len]

