def solve(weights, values, capacity):
    # 0/1 knapsack DP using 1D array, capacity may be int
    n=len(weights)
    dp=[0]*(capacity+1)
    for i in range(n):
        w=weights[i]
        v=values[i]
        # iterate backwards
        for c in range(capacity, w-1, -1):
            new=v+dp[c-w]
            if new>dp[c]:
                dp[c]=new
    return dp[capacity]

