    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Remove duplicates and ignore non‑positive coins
    coins = [c for c in set(coins) if c > 0]
    # DP array where dp[i] = min coins to make amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
