def solve(grid):
    """Count the number of islands (connected 1s) in a grid.
    Handles grids with rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # explore 4 directions
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

