def solve(grid):
    """Count islands in a binary grid where rows may have variable lengths.
    Returns the number of 4-directionally connected groups of 1s.
    The input grid is not mutated.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    count = 0

    def neighbors(r, c):
        for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    for nr, nc in neighbors(cr, cc):
                        if grid[nr][nc] == 1 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))
    return count

