def solve(coins, amount):
    """Return the minimum number of coins needed to make up amount.
    Unlimited supply of each coin in `coins`. Return -1 if impossible.
    Uses dynamic programming O(amount * len(coins)).
    """
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive coins
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

