{"task_id": "T48", "code": "def solve(n, edges):
    """Return the lexicographically smallest topological order for a DAG.
    If a cycle exists, return an empty list.
    Uses Kahn's algorithm with a min-heap to always pick the smallest available node.
    """
    from heapq import heappush, heappop
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Initialize heap with zero-indegree nodes
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) == n:
        return order
    return []"}

