def solve(s: str) -> bool:
    """Validate IPv4 address.
    Must consist of exactly four decimal numbers separated by dots.
    Each number is 0-255 inclusive, with no leading zeros unless the number is exactly 0.
    No extra whitespace or characters are allowed.
    """
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # each part must be non-empty, consist only of digits
        if not part or not part.isdigit():
            return False
        # no leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        # range check
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

